-- =======================================================
-- QUERY INSERT DATA MAHASISWA (87 DATA LENGKAP DENGAN RFID & KELAS)
-- Database: absensi_KA | Tabel: public.mahasiswa
-- =======================================================

ON CONFLICT (rfid_uid) DO UPDATE
SET nama = EXCLUDED.nama,
    nim = EXCLUDED.nim,
    kelas_id = EXCLUDED.kelas_id;
